"""🖼️ Figurinhas das palavras difíceis do 3º bimestre de 2027 (6º ao 9º ano), 21/11/2026. Desenhos em linha clara
feitos pelo Claude. Importado por termos.py. Sem fotos de pessoas e sem logos (marcas e órgãos aparecem só pelo nome escrito)."""
from linha_clara import V, K, t, r, c, p, etiqueta, seta_grossa
from termos_2027_1bim import kj, cel, blk, emo


def registrar(d, D, kp):
    pulados = []
    def dd(nomes, rot, corpo, cor="cinza"):
        novos = [n for n in nomes.split("|") if kp(n) not in D and kj(n) not in D]
        pulados.extend(n for n in nomes.split("|") if n not in novos)
        if not novos: return
        d("|".join(novos), rot, corpo, cor)
        for n in novos: D[kj(n)] = D[kp(n)]
    registrar.pulados = pulados
    E1 = lambda e, lab, cor="azul": emo(160, 100, e, 72) + etiqueta(160, 172, lab, cor, 12)
    E2 = lambda e1, e2, lab, cor="azul": emo(80, 100, e1, 56) + seta_grossa(120, 100, 196, cor, 24) + emo(242, 100, e2, 56) + etiqueta(160, 172, lab, cor, 12)
    EE = lambda es, lab, cor="azul": "".join(emo(160 + (i - (len(es) - 1) / 2) * 70, 100, e, 48) for i, e in enumerate(es)) + etiqueta(160, 172, lab, cor, 12)
    CARD = lambda linhas, e, cor="azul": r(50, 30, 220, 118, "#fff", rx=10, lw=3, sombra=3) + "".join(t(160, 62 + i * 26, s, 15, K, 900 if i == 0 else 700) for i, s in enumerate(linhas)) + emo(250, 150, e, 34)
